// Le jour de Paris, le mode et la COPIE FIGÉE des règles du code (scripts/apres-chantier-n8n-qa.mjs rougit si elle s'en écarte) :
// lib/apresChantier.ts (DELAI_AVIS_JOURS, RATTRAPAGE_JOURS, PREAVIS_JOURS, ENTRETIEN_ANS_MAX, EQUIPEMENTS), lib/apresChantierTour.ts
// (MAX_POSES_PAR_PASSAGE), lib/plans.ts (offres qui portent « crm ») et lib/flags.ts (crmApresChantier). Aucune donnée lue ici.
const jour = $now.setZone('Europe/Paris').toISODate();
const ajouterMois = (j, n) => {
  const a = +j.slice(0, 4), m = +j.slice(5, 7) - 1 + n, d = +j.slice(8, 10);
  const an = a + Math.floor(m / 12), mo = ((m % 12) + 12) % 12;
  const dernier = new Date(Date.UTC(an, mo + 1, 0)).getUTCDate();
  return new Date(Date.UTC(an, mo, Math.min(d, dernier))).toISOString().slice(0, 10);
};
return [{ json: {
  jour,
  depuis: ajouterMois(jour, -12 * 3),
  mode: 'simulation',
  drapeau_crmApresChantier: true,
  offres_crm: ['signature', 'entreprise'],
  seuils: { delai_avis_jours: 2, rattrapage_jours: 14, preavis_jours: 15, entretien_ans_max: 3, max_poses_par_passage: 20 },
  equipements: {
    chaudiere: { nom: 'chaudière', mois: 12 },
    pompe_a_chaleur: { nom: 'pompe à chaleur', mois: 24 },
    conduit_de_fumee: { nom: 'conduit de fumée', mois: 12 }
  }
} }];

// La règle de tourApresChantier (lib/apresChantierTour.ts:29-55) et de propositions (lib/apresChantier.ts:131-160), en code pur :
// pour chaque compte qui a coché « Demander un avis » ou « Proposer l'entretien » et dont l'offre porte le CRM (ou fondateur), les
// rappels de ses chantiers TERMINÉS, à la date de fin RÉELLE ; clé « avis:<chantier> » ou « entretien:<chantier>:<n> », jamais deux
// fois la même ; au plus 20 par compte, par échéance. Écarts voulus (brief c4-n8n-apres-chantier.md, « Comparaison ») :
//  É1 aucun nom de client lu : le texte dit « le client » ; É2 un chantier dont le client s'est opposé (0171) n'a plus de rappel ;
//  É4 un chantier sans ligne de signaux n'a aucun rappel (doute : rien). Pause générale illisible = active : rien n'est posé.
const ctx = $('Contexte du passage').first().json;
const S = ctx.seuils;
const JOUR = ctx.jour;
const lignes = (nom) => $(nom).all().map((i) => i.json).filter((r) => r && typeof r === 'object' && Object.keys(r).length > 0);
const jourMs = (j) => Date.UTC(+j.slice(0, 4), +j.slice(5, 7) - 1, +j.slice(8, 10));
const ajouterJours = (j, n) => new Date(jourMs(j) + n * 86400000).toISOString().slice(0, 10);
const ajouterMois = (j, n) => {
  const a = +j.slice(0, 4), m = +j.slice(5, 7) - 1 + n, d = +j.slice(8, 10);
  const an = a + Math.floor(m / 12), mo = ((m % 12) + 12) % 12;
  const dernier = new Date(Date.UTC(an, mo + 1, 0)).getUTCDate();
  return new Date(Date.UTC(an, mo, Math.min(d, dernier))).toISOString().slice(0, 10);
};
const finDe = (c) => c.statut === 'termine' && typeof c.date_fin_reelle === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(c.date_fin_reelle.slice(0, 10)) ? c.date_fin_reelle.slice(0, 10) : null;
// M2 (032-010) : toute jointure entre deux lectures passe par le compte ET l'identifiant.
const paire = (artisanId, id) => artisanId + '|' + id;
const pause = lignes('Lire pause generale');
const bilan = { jour: JOUR, mode: ctx.mode, pause: !(pause.length === 1 && pause[0].pause_generale === false), comptes: 0, poses: 0, sans_signal: 0, opposes: 0, a_poser: [] };
if (bilan.pause || ctx.drapeau_crmApresChantier !== true) return [{ json: bilan }];
const comptes = new Map(lignes('Lire comptes').map((a) => [a.id, a]));
const signaux = new Map(lignes('Lire signaux').map((s) => [paire(s.artisan_id, s.chantier_id), s]));
const chantiersDe = new Map(), clesDe = new Map();
for (const c of lignes('Lire chantiers')) { if (!chantiersDe.has(c.artisan_id)) chantiersDe.set(c.artisan_id, []); chantiersDe.get(c.artisan_id).push(c); }
for (const k of lignes('Lire cles')) { if (!clesDe.has(k.artisan_id)) clesDe.set(k.artisan_id, new Set()); if (typeof k.cle === 'string') clesDe.get(k.artisan_id).add(k.cle); }
for (const reg of lignes('Lire reglages').filter((x) => x.avis === true || x.entretien === true)) {
  const p = comptes.get(reg.artisan_id);
  if (!p || (p.is_founder !== true && !ctx.offres_crm.includes(p.plan))) continue;
  bilan.comptes++;
  const existantes = clesDe.get(reg.artisan_id) || new Set();
  const activation = (typeof reg.actif_depuis === 'string' ? reg.actif_depuis : '').slice(0, 10) || JOUR;
  const qui = 'le client';
  const out = [];
  for (const c of chantiersDe.get(reg.artisan_id) || []) {
    const fin = finDe(c);
    if (!fin || fin > JOUR) continue;
    const sig = signaux.get(paire(reg.artisan_id, c.id));
    if (!sig) { bilan.sans_signal++; continue; }
    if (sig.oppose !== false) { bilan.opposes++; continue; }
    if (reg.avis === true && fin >= ajouterJours(activation, -S.rattrapage_jours)) {
      const cle = 'avis:' + c.id;
      if (!existantes.has(cle)) {
        const due = ajouterJours(fin, S.delai_avis_jours);
        out.push({ cle, chantier_id: c.id, type: 'demande_avis', echeance: due > JOUR ? due : JOUR, texte: ('Demander un avis à ' + qui).slice(0, 300) });
      }
    }
    const eq = reg.entretien === true && typeof sig.equipement === 'string' ? ctx.equipements[sig.equipement] || null : null;
    if (eq && fin >= ajouterMois(JOUR, -12 * S.entretien_ans_max)) {
      let n = 1;
      while (ajouterJours(ajouterMois(fin, n * eq.mois), -S.preavis_jours) < JOUR && n < 100) n++;
      const cle = 'entretien:' + c.id + ':' + n;
      if (!existantes.has(cle) && ![...existantes].some((k) => k.startsWith('entretien:' + c.id + ':') && Number(k.split(':')[2]) >= n)) {
        out.push({ cle, chantier_id: c.id, type: 'entretien', echeance: ajouterJours(ajouterMois(fin, n * eq.mois), -S.preavis_jours), texte: ('Proposer l’entretien (' + eq.nom + ') à ' + qui).slice(0, 300) });
      }
    }
  }
  const aPoser = out.sort((a, b) => a.echeance.localeCompare(b.echeance)).slice(0, S.max_poses_par_passage);
  for (const x of aPoser) bilan.a_poser.push(Object.assign({ artisan_id: reg.artisan_id }, x));
  bilan.poses += aPoser.length;
}
return [{ json: bilan }];

// L'ÉCRITURE, EN SIMULATION (tâche 032-031) : les lignes que l'ancien code envoie à crm_rappels (upsert, conflit artisan_id,cle,
// doublons ignorés : app/api/cron/relances/route.ts, poser), préparées ici et NON écrites. Aucune requête ne part de ce nœud.
// L'écriture réelle est un pas de la bascule, sur le « go » de Benj (brief c4-n8n-apres-chantier.md, « Avant la bascule »).
const b = $input.first().json;
const lignes = (b.a_poser || []).map((p) => ({ artisan_id: p.artisan_id, chantier_id: p.chantier_id, type: p.type, echeance: p.echeance, origine: 'systeme', cle: p.cle, texte: p.texte }));
return [{ json: { mode: 'simulation', ecrit: false, table: 'crm_rappels', conflit: 'artisan_id,cle', doublons: 'ignores', jour: b.jour, pause: b.pause, comptes: b.comptes, poses: lignes.length, sans_signal: b.sans_signal, opposes: b.opposes, lignes } }];

// Branche d'erreur (plan §0 bis, rang 26) : le message d'alerte, sans aucune donnée lue ni texte d'erreur (qui pourrait en porter).
// L'envoi vers #presti-auto attend l'identifiant et le « go » de Benj : aucun nœud d'envoi ici. Une lecture en erreur arrête tout le
// passage : rien n'est posé (au lieu de sauter le seul compte fautif, comme l'ancien code : écart É5 du brief).
const e = $input.first().json || {};
const x = e.execution && typeof e.execution === 'object' ? e.execution : {};
const propre = (v, n) => String(v === undefined || v === null ? '' : v).replace(/[^A-Za-z0-9 _()'éèêàâçôîûù-]/g, '').slice(0, n);
return [{ json: { alerte: 'presti-apres-chantier a échoué', noeud: propre(x.lastNodeExecuted, 80) || 'inconnu', execution: propre(x.id, 40), mode: propre(x.mode, 20) } }];
